import { createServerApp, authFixture, readHydrationState, type ComponentRpcRequest } from '@cossackframework/test-utils/server';
export async function assertProtectedApp<Env>(fetch: (request: Request, env: Env) => Response | Promise<Response>, env: Env, rpc: ComponentRpcRequest) {
  const app = createServerApp({fetch, env, baseUrl: 'https://app.example.test'});
  const anonymous = await app.request('/account');
  if (anonymous.status !== 403) throw Error('Anonymous route must be denied');
  const credentials = authFixture({cookies: {session: 'valid-test-session'}});
  const allowed = await app.request('/account', credentials);
  if (allowed.status !== 200 || !readHydrationState(await allowed.text())) throw Error('Missing authorized SSR state');
  const response = await app.componentRpc(rpc, credentials);
  if (response.status !== 200) throw Error('Authorized RPC failed');
}

import { withRequestScope, controlledAsync } from '@cossackframework/test-utils/server';
const ready = controlledAsync<string>();
const first = withRequestScope({user: {id: 'alice'}}, async ({serviceScope}) => {
  if (!serviceScope) throw Error('Missing request DI scope');
  return ready.promise;
});
const second = withRequestScope({user: {id: 'bob'}}, async () => {ready.resolve('finished'); return 'bob';});
const results = await Promise.all([first, second]);
if (results.join(',') !== 'finished,bob') throw Error('Unexpected request results');

import { render } from '@cossackframework/test-utils/browser';
import { Cossack } from '@cossackframework/core';
import { html } from '@cossackframework/renderer';
class Greeting extends Cossack {
  render() { return html`<p>hello</p>`; }
}
export async function assertGreetingInBrowser() {
  const view = await render(Greeting);
  try { if (!view.container.querySelector('p') || !view.html().includes('hello')) throw Error('Missing greeting'); }
  finally { await view.unmount(); }
  if (view.container.isConnected) throw Error('Unmount did not remove container');
}
